package control

import (
	"encoding/json"
	"os"
	"reflect"
	"testing"

	"github.com/go-telegram/bot/models"
)

func TestMenusMatchLegacyCheckpoint(t *testing.T) {
	// Generated by executing the command arrays at checkpoint checkpoint-typescript-baseline.
	b, err := os.ReadFile("testdata/legacy-menus.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden map[string][]models.BotCommand
	if err := json.Unmarshal(b, &golden); err != nil {
		t.Fatal(err)
	}
	for name, commands := range map[string][]models.BotCommand{"member": Commands(false, false), "master": Commands(true, false), "management": Commands(true, true)} {
		if !reflect.DeepEqual(commands, golden[name]) {
			t.Fatalf("%s menu differs from legacy checkpoint", name)
		}
	}
}
